// Static SPA. Cognito Hosted UI (authorization code + PKCE). config.json is generated by scripts/deploy.sh.
let cfg, token;
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const b64url = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
async function pkce() {
  const verifier = b64url(crypto.getRandomValues(new Uint8Array(32)));
  const challenge = b64url(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)));
  return { verifier, challenge };
}
const redirectUri = () => location.origin + "/";

async function login() {
  const { verifier, challenge } = await pkce();
  sessionStorage.setItem("pkce", verifier);
  const q = new URLSearchParams({ response_type: "code", client_id: cfg.clientId, redirect_uri: redirectUri(), scope: "openid email", code_challenge_method: "S256", code_challenge: challenge });
  location.href = `https://${cfg.cognitoDomain}/oauth2/authorize?${q}`;
}

async function exchange(code) {
  const body = new URLSearchParams({ grant_type: "authorization_code", client_id: cfg.clientId, code, redirect_uri: redirectUri(), code_verifier: sessionStorage.getItem("pkce") });
  const r = await fetch(`https://${cfg.cognitoDomain}/oauth2/token`, { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body });
  if (!r.ok) throw new Error("login failed");
  const t = await r.json();
  sessionStorage.setItem("idToken", t.id_token);
  history.replaceState({}, "", "/");
  return t.id_token;
}

// The Cognito id token lasts 60 minutes. Treat an expired one as signed out instead of failing every call with 401.
const jwtExpired = (t) => { try { return JSON.parse(atob(t.split(".")[1].replace(/-/g, "+").replace(/_/g, "/"))).exp * 1000 < Date.now() + 30000; } catch { return true; } };
function expireSession() {
  sessionStorage.removeItem("idToken"); token = null;
  $("app").hidden = true;
  $("auth").innerHTML = '<p class="warn">Your session expired. Sign in again.</p><button id="login">Sign in</button>';
  $("login").onclick = login;
  throw new Error("session expired");
}

async function api(path, opts = {}) {
  if (!token || jwtExpired(token)) expireSession();
  const r = await fetch(cfg.apiUrl + path, { ...opts, headers: { authorization: token, "content-type": "application/json" } });
  if (r.status === 401) expireSession();
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || r.statusText);
  return data;
}

async function download(runId, name) {
  try {
    const { url, filename } = await api(`/runs/${runId}/artifacts/${name}`);
    const a = Object.assign(document.createElement("a"), { href: url, download: filename });
    document.body.appendChild(a); a.click(); a.remove();
  } catch (e) { $("run").insertAdjacentHTML("afterbegin", `<p class="err">${esc(e.message)}</p>`); }
}

async function approve(runId) {
  try { await api(`/runs/${runId}/approvals`, { method: "POST", body: JSON.stringify({ gate: "A" }) }); await load(); }
  catch (e) { $("run").insertAdjacentHTML("afterbegin", `<p class="err">${esc(e.message)}</p>`); }
}

const list = (items, f) => (items.length ? `<ul>${items.map(f).join("")}</ul>` : '<div class="muted">none</div>');
const tag = (b) => `<span class="tag">${esc(b)}</span>`;

// Org tree: the Mermaid text is generated by the server from the validated scope, never by the model.
const diagramCache = new Map();  // mermaid text -> rendered svg, so the 8s refresh does not redraw or flicker
const LEGEND = [["#dbeafe", "#1d4ed8", "Created by the stacks"], ["#ede9fe", "#6d28d9", "Created by Control Tower"],
  ["#e2e8f0", "#334155", "Must already exist"], ["#fff", "#64748b", "In the SOW, not created by the stacks (dashed)"]];

function diagramCard(text) {
  const svg = diagramCache.get(text) || "";
  return `<div class="card"><b>Organization structure</b>
    <div class="legend">${LEGEND.map(([bg, bd, t]) => `<span><i style="background:${bg};border-color:${bd}"></i>${esc(t)}</span>`).join("")}</div>
    <div class="diagram" id="orgdiagram">${svg || '<span class="muted">Drawing...</span>'}</div>
    <details><summary class="muted">Diagram source</summary><pre><code>${esc(text)}</code></pre></details></div>`;
}

async function drawDiagram(text) {
  const box = $("orgdiagram");
  if (!box || diagramCache.has(text)) return;
  try {
    mermaid.initialize({ startOnLoad: false, securityLevel: "strict", theme: "default" });
    const { svg } = await mermaid.render("orgsvg" + Date.now(), text);
    diagramCache.set(text, svg);
    if ($("orgdiagram")) $("orgdiagram").innerHTML = svg;
  } catch { box.innerHTML = '<span class="err">The diagram could not be drawn. The source is below.</span>'; }
}

function scopeHtml(s) {
  const r = s.regions, lg = s.logging;
  return `<div class="card">
    <b>Extracted scope</b> <span class="tag">${esc(s.status)}</span>
    ${s.missingRequired.length ? `<p class="warn">Missing required input: ${esc(s.missingRequired.join(", "))}. Fill these in the stack parameters before deploying.</p>` : ""}
    ${(s.warnings || []).length ? `<p class="warn">${(s.warnings || []).map((w) => esc(w)).join("<br>")}</p>` : ""}
    <h3>Regions</h3>
    <div>Home <code>${esc(r.home)}</code> · governed ${r.governed.map((x) => `<code>${esc(x)}</code>`).join(" ")}</div>
    <div>Extra allowed: ${r.extraAllowed.map((x) => `<code>${esc(x)}</code>`).join(" ") || "none"} · region deny enforced: ${r.enforceDeny}</div>
    <div class="muted">Denied (${r.denied.length}, derived): ${esc(r.denied.join(", "))}</div>
    <h3>Logging</h3>
    <div>Retention ${lg.retentionDays} days (access logs ${lg.accessLogRetentionDays}) · log archive ${esc(lg.logArchiveAccountId || "NOT PROVIDED")} · audit ${esc(lg.auditAccountId || "NOT PROVIDED")}</div>
    <h3>OUs created (${s.ous.length})</h3>${list(s.ous, (o) => `<li>${esc(o.name)}${o.parent ? ` <span class="muted">(under ${esc(o.parent)})</span>` : ""} ${tag(o.basis)}</li>`)}
    <h3>Accounts (${(s.accounts || []).length}, for context: the stacks do not create them)</h3>${list(s.accounts || [], (a) => `<li>${esc(a.name)} <span class="muted">${esc(a.kind)}, ${esc(a.provisioning)}, in ${esc(a.ou)}</span> ${tag(a.basis)}</li>`)}
    <h3>Service control policies (${s.scps.length}, applied by the stacks)</h3>${list(s.scps, (p) => `<li><code>${esc(p.id)}</code> on ${esc(p.targets.join(", "))} ${tag(p.basis)}</li>`)}
    <h3>Custom SCPs (${(s.customScps || []).length}, model-authored, not applied)</h3>${list(s.customScps || [], (p) => `<li><code>${esc(p.id)}</code> ${esc(p.title || "")} on ${esc((p.targets || []).join(", "))} ${tag(p.basis)}<details><summary class="muted">Policy document</summary><pre><code>${esc(JSON.stringify(p.document, null, 2))}</code></pre></details></li>`)}
    <h3>Control Tower controls (${s.controls.length} controls, ${s.summary.controlAttachments} attachments)</h3>${list(s.controls, (c) => `<li><code>${esc(c.id)}</code> on ${esc(c.targets.join(", "))} ${tag(c.basis)}</li>`)}
    <h3>Not codified (${s.unsupported.length})</h3>${list(s.unsupported, (u) => `<li>${esc(u.requirement)}: <span class="muted">${esc(u.reason)}</span></li>`)}
    <h3>Assumptions</h3>${list(s.assumptions, (a) => `<li>${esc(a)}</li>`)}
    <h3>Open questions</h3>${list(s.openQuestions, (q) => `<li>${esc(q)}</li>`)}
  </div>`;
}

const remember = (id) => { try { localStorage.setItem("lastRunId", id); } catch { /* storage blocked */ } };
const recall = () => { try { return localStorage.getItem("lastRunId") || ""; } catch { return ""; } };

async function loadRuns() {
  const { runs } = await api("/runs");
  $("runs").innerHTML = runs.length
    ? `<table><tr><th>Customer</th><th>Status</th><th>Started</th><th>Run id</th></tr>${runs.map((r) => `<tr data-run="${esc(r.runId)}" style="cursor:pointer">
        <td>${esc(r.customerId)}</td>
        <td><span class="${r.status === "FAILED" ? "err" : r.status === "DELIVERED" ? "okc" : ""}">${esc(r.status)}</span>${r.status === "FAILED" && r.error ? `<div class="muted">${esc(r.error)}</div>` : ""}</td>
        <td>${new Date(r.createdAt * 1000).toLocaleString()}</td><td><code>${esc(r.runId)}</code></td></tr>`).join("")}</table>`
    : '<div class="muted">No runs yet.</div>';
  $("runs").querySelectorAll("[data-run]").forEach((tr) => (tr.onclick = () => { $("runId").value = tr.dataset.run; load().catch(() => {}); }));
  return runs;
}

async function load() {
  const runId = $("runId").value.trim();
  if (!runId) return;
  remember(runId);
  const { run, openGates, approvals } = await api(`/runs/${runId}`);
  if (run.status === "FAILED") {  // a failed run cannot be resumed: show why, and the scan report if validation produced one
    const report = run.artifacts && run.artifacts.report
      ? `<p><button class="secondary" data-dl="report">Validation report</button></p>` : "";
    $("run").innerHTML = `<div class="card"><b>${esc(run.customerId)}</b> · <span class="err">FAILED</span>
      <div class="err">${esc(run.error || "No error recorded.")}</div>
      ${report}
      <div class="muted">This run failed and cannot be resumed. Start a new run.</div></div>`;
    $("run").querySelectorAll("[data-dl]").forEach((b) => (b.onclick = () => download(runId, b.dataset.dl)));
    const { audit } = await api(`/runs/${runId}/audit`);
    $("audit").innerHTML = `<table><tr><th>Time</th><th>Actor</th><th>Action</th></tr>${audit.map((a) => `<tr><td>${new Date(a.ts * 1000).toLocaleString()}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td></tr>`).join("")}</table>`;
    return;
  }
  let scopeBlock = "", diagramText = "";
  if (run.artifacts && run.artifacts.intake) {
    try {
      const r = await api(`/runs/${runId}/scope`);
      scopeBlock = scopeHtml(r.scope); diagramText = r.orgDiagram || "";
    } catch { /* not ready */ }
  }
  const delivered = run.status === "DELIVERED";
  $("run").innerHTML = `
    <div class="card"><b>${esc(run.customerId)}</b> · <span>${esc(run.status)}</span>
      ${run.error ? `<div class="err">${esc(run.error)}</div>` : ""}</div>
    ${openGates.map((g) => `<div class="card"><b>Scope awaiting approval</b>
        <div class="muted">You are approving scope <code>${esc(g.sha)}</code>. The stacks are generated from exactly this.</div>
        <p><button data-ap="1">Approve scope</button></p></div>`).join("")}
    ${approvals.map((a) => `<div class="card okc">Scope approved by <code>${esc(a.approver)}</code></div>`).join("")}
    ${diagramText ? diagramCard(diagramText) : ""}
    ${scopeBlock}
    <div class="card"><b>Stacks</b>
      <p class="row"><button data-dl="terraform" ${delivered ? "" : "disabled"}>Download Terraform</button>
      <button data-dl="cloudformation" ${delivered ? "" : "disabled"}>Download CloudFormation</button>
      <button class="secondary" data-dl="report" ${run.artifacts && run.artifacts.report ? "" : "disabled"}>Validation report</button></p>
      <div class="muted">${delivered ? "Both stacks passed validation. Each download includes the agent session and the code-scan reports." : "Available after approval and validation."}</div></div>`;
  $("run").querySelectorAll("[data-dl]").forEach((b) => (b.onclick = () => download(runId, b.dataset.dl)));
  $("run").querySelectorAll("[data-ap]").forEach((b) => (b.onclick = () => approve(runId)));
  if (diagramText) drawDiagram(diagramText);
  const { audit } = await api(`/runs/${runId}/audit`);
  $("audit").innerHTML = `<table><tr><th>Time</th><th>Actor</th><th>Action</th></tr>${audit.map((a) => `<tr><td>${new Date(a.ts * 1000).toLocaleString()}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td></tr>`).join("")}</table>`;
}

async function create() {
  const msg = $("createMsg"); msg.textContent = ""; $("create").disabled = true;
  try {
    const f = $("file").files[0];
    const { runId, upload } = await api("/runs", { method: "POST", body: JSON.stringify({ customerId: $("customer").value, requirements: $("req").value, fileName: f ? f.name : "" }) });
    if (upload) {
      msg.textContent = "Uploading...";
      const fd = new FormData();
      Object.entries(upload.fields).forEach(([k, v]) => fd.append(k, v));
      fd.append("file", f);
      const up = await fetch(upload.url, { method: "POST", body: fd });
      if (!up.ok) throw new Error("upload failed (" + up.status + ")");
    }
    await api(`/runs/${runId}/start`, { method: "POST" });
    $("runId").value = runId; msg.textContent = "Started."; await load(); await loadRuns();
  } catch (e) { msg.innerHTML = `<span class="err">${esc(e.message)}</span>`; }
  finally { $("create").disabled = false; }
}

(async () => {
  cfg = await (await fetch("/config.json")).json();
  const code = new URLSearchParams(location.search).get("code");
  token = code ? await exchange(code) : sessionStorage.getItem("idToken");
  const expired = token && jwtExpired(token);
  if (!token || expired) {
    sessionStorage.removeItem("idToken"); token = null;
    $("auth").innerHTML = `${expired ? '<p class="warn">Your session expired. Sign in again.</p>' : ""}<button id="login">Sign in</button>`;
    $("login").onclick = login; return;
  }
  $("auth").innerHTML = '<button class="secondary" id="logout">Sign out</button>';
  $("logout").onclick = () => { sessionStorage.clear(); location.href = `https://${cfg.cognitoDomain}/logout?client_id=${cfg.clientId}&logout_uri=${encodeURIComponent(redirectUri())}`; };
  $("app").hidden = false;
  $("create").onclick = create; $("load").onclick = load;
  // reopen the last viewed run (or the newest one) so a page refresh keeps your place
  $("runId").value = recall();
  try { const runs = await loadRuns(); if (!$("runId").value && runs.length) $("runId").value = runs[0].runId; } catch { /* list unavailable */ }
  if ($("runId").value) load().catch(() => {});
  setInterval(() => { if ($("poll").checked) { loadRuns().catch(() => {}); if ($("runId").value) load().catch(() => {}); } }, 8000);
})();
